import { isString } from 'lodash-es';
import React, { forwardRef } from 'react';
import styled, { CSSObject } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { _useId } from '../../../../core/hooks/useId.js';
import { _useSharedInputPropsContext } from '../../../../core/hooks/useSharedInputPropsContext.js';
import type { DataTestId } from '../../../../core/types/data-props.js';
import type { DOMProps } from '../../../../core/types/dom.js';
import type { StylingProps } from '../../../../core/types/styling-props.js';
import type { WithChildren } from '../../../../core/types/with-children.js';
import { Text } from '../../../../typography/Text.js';
import { _useFormFieldContext } from '../../hooks/useFormFieldContext.js';

/** Available options for the label size */
export interface LabelProps
  extends WithChildren,
    DOMProps,
    StylingProps,
    DataTestId {
  /** Defines the id of a labelable form related field. */
  htmlFor?: string;

  /**
   * If there is a wrapping form field then this label uses the required value
   * from the form field, otherwise it uses this required value. The label
   * has a visual style to indicate the associated field is a mandatory field.
   * @defaultValue false
   */
  required?: boolean;

  /**
   * If there is a wrapping form field then this label uses the disabled value
   * from the form field, otherwise it uses this disabled value. The label
   * has a visual style to indicate the associated field is disabled.
   * @defaultValue false
   */
  disabled?: boolean;
}

// #region StyledComponents
const StyledSimpleLabel = /* @__PURE__ */ styled(Text)<{
  $required: boolean;
  $disabled: boolean;
}>((props) => {
  const base: CSSObject = {
    display: 'inline-block',
    color: props.$disabled ? Colors.Text.Neutral.Disabled : undefined,
  };
  if (props.$required) {
    return {
      ...base,
      '&:after': {
        content: '"*"',
      },
    };
  }
  return base;
});

const StyledComplexLabel = /* @__PURE__ */ styled('label')<{
  $disabled: boolean;
}>((props) => ({
  display: 'inline-block',
  color: props.$disabled ? Colors.Text.Neutral.Disabled : undefined,
}));
// #endregion

/**
 * The `Label` component allows users to add an associated text to another
 * form control by using the `FormField` component.
 */
export const Label = /* @__PURE__ */ forwardRef<HTMLLabelElement, LabelProps>(
  (props, forwardedRef) => {
    const {
      id,
      children,
      htmlFor,
      disabled: propDisabled = false,
      required: propRequired = false,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: LabelProps = props;

    const generatedId = _useId();

    const {
      controlId: formFieldContextId,
      required,
      disabled,
    } = _useFormFieldContext();

    const {
      id: sharedInputContextId,
      required: sharedInputRequired,
      disabled: sharedInputDisabled,
      labelId,
    } = _useSharedInputPropsContext({
      disabled: disabled ?? propDisabled,
      required: required ?? propRequired,
      labelId: id ?? generatedId,
    });

    const StyledLabel = isString(children)
      ? StyledSimpleLabel
      : StyledComplexLabel;

    const labelFor = htmlFor || formFieldContextId || sharedInputContextId;

    return (
      <StyledLabel
        // eslint-disable-next-line @typescript-eslint/prefer-ts-expect-error, @typescript-eslint/ban-ts-comment
        // @ts-ignore: forwardAs only exists for the styled(Text) option.
        forwardedAs="label"
        htmlFor={labelFor}
        id={id ?? labelId}
        data-testid={dataTestId}
        $disabled={propDisabled || sharedInputDisabled}
        $required={propRequired || sharedInputRequired}
        ref={forwardedRef}
        textStyle="small-emphasized"
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </StyledLabel>
    );
  },
);
(Label as typeof Label & { displayName: string }).displayName = 'Label';
